INSERT INTO rupture_alternatives (rupture_id, produit_alternatif, commentaire) VALUES
('d0000000-0000-4000-8000-000000000001', 'VMP-000106', 'Même boîte, emballage plus triste. Le pharmacien dit que ça tient, le comité dit qu''on verra en réunion.'),
('d0000000-0000-4000-8000-000000000001', 'VMP-000114', 'Couleur orange pâle, goût de rien. Très efficace contre l''attente, à condition de ne pas la goûter.'),
('d0000000-0000-4000-8000-000000000002', 'VMP-000117', 'Le sirop est bien là, mais le bouchon est dans un autre département. Commander deux fois pour être sûr.'),
('d0000000-0000-4000-8000-000000000004', 'VMP-000105', 'Gouttes au formulaire 12B : il faut remplir le 12B avant de les recevoir. Ça marche, mais lentement.'),
('d0000000-0000-4000-8000-000000000004', 'VMP-000108', 'Crème hydratante du comité. Hydrate les mains du demandeur pendant qu''il attend la validation.'),
('d0000000-0000-4000-8000-000000000006', 'VMP-000119', 'Capsule attestée conforme, c''est écrit sur la boîte. Le contenu reste à confirmer, mais la boîte est très belle.'),
('d0000000-0000-4000-8000-000000000008', 'VMP-000101', 'Même molécule imaginaire, même notice imaginaire. Le fabricant conseille de relire la notice deux fois.'),
('d0000000-0000-4000-8000-000000000008', 'VMP-000110', 'Injectable sans notice : la notice arrivera dans un second temps, par courrier, en même temps que la facture.'),
('d0000000-0000-4000-8000-000000000008', 'VMP-000122', 'Comprimé pelliculé déjà vu l''an dernier. Stock encore disponible, selon un rapport qui date de l''an dernier.'),
('d0000000-0000-4000-8000-000000000010', 'VMP-000111', 'Patch rétro-validé : il colle très bien à la validation, un peu moins au calendrier. Demande à confirmer.'),
('d0000000-0000-4000-8000-000000000010', 'VMP-000121', 'Lyophilisat sans parenthèse, donc sans ambiguïté. Le seul défaut : il faut le dissoudre dans un formulaire.'),
('d0000000-0000-4000-8000-000000000010', 'VMP-000103', 'Réunionite forte en gélules, à défaut de réunion. Le stock suit le calendrier des réunions.'),
('d0000000-0000-4000-8000-000000000011', 'VMP-000102', 'Sirop du lundi matin : disponible le lundi matin, à condition d''arriver avant 9 h 15.'),
('d0000000-0000-4000-8000-000000000012', 'VMP-000116', 'Gélule anti-doublon : on ne la trouve qu''une fois, c''est le principe.'),
('d0000000-0000-4000-8000-000000000012', 'VMP-000113', 'Suppositoire recommandé AR : il arrive, mais il faut signer le bon de réception au préalable.'),
('d0000000-0000-4000-8000-000000000014', 'VMP-000109', 'Sachet tiède multi-usage, tiède depuis trois semaines. Toujours utile pour patienter.'),
('d0000000-0000-4000-8000-000000000014', 'VMP-000125', 'Collutoire anti-relance : il ne relance personne, c''est bien son seul défaut.'),
('d0000000-0000-4000-8000-000000000015', 'VMP-000104', 'Pastille anti-file d''attente : elle permet de ne pas attendre la file, mais la file n''attend pas la pastille.'),
('d0000000-0000-4000-8000-000000000016', 'VMP-000107', 'Ampoule de la dernière minute, à utiliser avant la dernière minute. Après, c''est une autre ampoule.'),
('d0000000-0000-4000-8000-000000000016', 'VMP-000118', 'Pommade du quatrième bureau : elle arrive au quatrième bureau, qui est toujours au même étage.'),
('d0000000-0000-4000-8000-000000000018', 'VMP-000112', 'Poudre effervescente de mardi : mardi prochain, si la pompe à poudre fonctionne.'),
('d0000000-0000-4000-8000-000000000018', 'VMP-000120', 'Granulés du jeudi férié : pas de livraison ce jour-là, sauf urgence déclarée un autre jeudi.'),
('d0000000-0000-4000-8000-000000000018', 'VMP-000128', 'Bâton anti-stress administratif, sans mode d''emploi. Il fait son effet, d''après le formulaire de satisfaction.'),
('d0000000-0000-4000-8000-000000000019', 'VMP-000115', 'Solution buvable sous réserve : la réserve est documentée, la solution aussi, reste le camion.'),
('d0000000-0000-4000-8000-000000000021', 'VMP-000123', 'Ovule de la salle d''attente : on en a un très bon souvenir, il est juste un peu loin.'),
('d0000000-0000-4000-8000-000000000021', 'VMP-000126', 'Tisane bien tamponnée, pour ceux qui aiment les tampons. Infusion lente, comme tout le reste.'),
('d0000000-0000-4000-8000-000000000022', 'VMP-000129', 'Mousse sans mode d''emploi : elle se trouve, on ne sait juste pas comment l''utiliser.'),
('d0000000-0000-4000-8000-000000000023', 'VMP-000130', 'Sérum du pôle ouvert : ouvert, certes, mais le pôle n''a pas encore reçu sa clé.'),
('d0000000-0000-4000-8000-000000000023', 'VMP-000101', 'Patientol 500 mg : toujours une option, à condition de rester calme, ce qui est le principe du nom.'),
('d0000000-0000-4000-8000-000000000024', 'VMP-000105', 'Gouttes du formulaire 12B, toujours le même formulaire. Le 12B a fait le tour du bureau.'),
('d0000000-0000-4000-8000-000000000024', 'VMP-000117', 'Sirop bis-deux-fois-rien : deux fois rien, c''est déjà quelque chose, disent les distributeurs.'),
('d0000000-0000-4000-8000-000000000024', 'VMP-000121', 'Lyophilisat sans parenthèse, la parenthèse a été retirée lors de la dernière relecture.'),
('d0000000-0000-4000-8000-000000000026', 'VMP-000106', 'Collyre vert tamponné : pour les yeux comme pour les dossiers, il faut bien regarder le tampon.'),
('d0000000-0000-4000-8000-000000000026', 'VMP-000127', 'Pastilles du week-end prolongé : disponibles, à condition que le week-end dure assez longtemps.'),
('d0000000-0000-4000-8000-000000000027', 'VMP-000114', 'Comprimé orange pâle sans goût : il n''a pas de goût, mais il a une couleur, c''est déjà ça.'),
('d0000000-0000-4000-8000-000000000029', 'VMP-000110', 'Injectable sans notice : toujours sans notice, mais avec un bon de commande.'),
('d0000000-0000-4000-8000-000000000029', 'VMP-000122', 'Comprimé pelliculé déjà vu : vu dans un autre rapport, à une autre date.'),
('d0000000-0000-4000-8000-000000000030', 'VMP-000103', 'Réunionite forte, à prendre avec une réunion de suivi. Indication : le lundi.'),
('d0000000-0000-4000-8000-000000000030', 'VMP-000108', 'Crème hydratante du comité : elle hydrate surtout les formulaires.'),
('d0000000-0000-4000-8000-000000000030', 'VMP-000116', 'Gélule anti-doublon, la seule qui n''existe qu''en un exemplaire. Rare, donc précieuse.'),
('d0000000-0000-4000-8000-000000000031', 'VMP-000106', 'Collyre vert tamponné, toujours tamponné, toujours vert. Un classique du bureau.'),
('d0000000-0000-4000-8000-000000000032', 'VMP-000119', 'Capsule attestée conforme : la mention est sur la boîte, la preuve est dans un autre classeur.'),
('d0000000-0000-4000-8000-000000000032', 'VMP-000111', 'Patch rétro-validé, on le colle après coup. Pratique pour les dossiers déjà refermés.'),
('d0000000-0000-4000-8000-000000000034', 'VMP-000101', 'Patientol 500 mg, la valeur sûre. Toujours disponible dans le bon département, pas toujours dans le bon étage.'),
('d0000000-0000-4000-8000-000000000034', 'VMP-000102', 'Sirop du lundi matin, en secours le mardi. Le mardi reste à valider.'),
('d0000000-0000-4000-8000-000000000035', 'VMP-000115', 'Solution buvable sous réserve, sous réserve que le camion passe avant le déjeuner.'),
('d0000000-0000-4000-8000-000000000036', 'VMP-000117', 'Sirop bis-deux-fois-rien, pour une fois en double, ce qui rassure le stock.'),
('d0000000-0000-4000-8000-000000000036', 'VMP-000123', 'Ovule de la salle d''attente, déjà présent. La salle d''attente a été repeinte, pas l''ovule.'),
('d0000000-0000-4000-8000-000000000037', 'VMP-000104', 'Pastille anti-file d''attente : le principe est bon, la file est toujours là.'),
('d0000000-0000-4000-8000-000000000038', 'VMP-000101', 'Patientol 500 mg, en attendant que la demande se calme. Peu de chance, mais on essaie.'),
('d0000000-0000-4000-8000-000000000039', 'VMP-000119', 'Capsule attestée conforme, attestée à la date de la boîte, pas à celle du jour.'),
('d0000000-0000-4000-8000-000000000039', 'VMP-000121', 'Lyophilisat sans parenthèse, plus simple à commander à deux.'),
('d0000000-0000-4000-8000-000000000039', 'VMP-000124', 'Ampoule buvable rétrospective : elle regarde en arrière, comme le rapport qui la mentionne.');
